function weeklyStats(rows, nowIso) {
  const since = Date.parse(nowIso) - 7 * 86400000;
  const recent = rows.filter((r) => Date.parse(r.received_at) >= since);
  const count = (key) => recent.reduce((m, r) => ((m[r[key] || "unknown"] = (m[r[key] || "unknown"] || 0) + 1), m), {});
  const top = (obj) => Object.entries(obj).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k, v]) => `${k} (${v})`);
  return {
    total: recent.length,
    by_severity: count("severity"),
    top_hosts: top(count("host")),
    top_alerts: top(count("title")),
    open_critical: recent.filter((r) => ["critical", "high"].includes(r.severity) && String(r.status).toLowerCase() !== "closed")
      .map((r) => `${r.received_at.slice(0, 10)} ${r.title} on ${r.host || "?"}`).slice(0, 20),
  };
}

const rows = $input.all().map((i) => i.json).filter((r) => r.received_at);
const st = weeklyStats(rows, new Date().toISOString());
const sev = Object.entries(st.by_severity).map(([k, v]) => k + ': ' + v).join(', ') || 'none';
const text = [
  'Alerts in the last 7 days: ' + st.total + ' (' + sev + ')',
  '', 'Most affected hosts: ' + (st.top_hosts.join(', ') || 'none'),
  'Most frequent alerts: ' + (st.top_alerts.join(', ') || 'none'),
  '', 'High or critical alerts still open:', ...(st.open_critical.length ? st.open_critical.map((x) => '- ' + x) : ['- none']),
].join('\n');
return [{ json: { total: st.total, text }, pairedItem: { item: 0 } }];
